import{_ as p,a0 as r,w as n,s as o,ao as d,I as l,x as e,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用 coredumpctl 更好地记录 bug | LCTT x X-CMD","titleTemplate":false,"description":"用 coredumpctl 更好地记录 bug | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 coredumpctl 更好地记录 bug | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 coredumpctl 更好地记录 bug | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171110 File better bugs with coredumpctl","title":"用 coredumpctl 更好地记录 bug","tag":"201711","desc":""},"relativePath":"201711/20171110 File better bugs with coredumpctl.md","filePath":"[post].md"}'),g={name:"201711/20171110 File better bugs with coredumpctl.md"};function u(b,t,h,k,c,f){const s=r("Link");return n(),o("div",null,[t[21]||(t[21]=d('<h1 id="用-coredumpctl-更好地记录-bug" tabindex="-1">用 coredumpctl 更好地记录 bug <a class="header-anchor" href="#用-coredumpctl-更好地记录-bug" aria-label="Permalink to “用 coredumpctl 更好地记录 bug”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/11/coredump.png-945x400.jpg" alt=""></p><p>一个不幸的事实是，所有的软件都有 bug，一些 bug 会导致系统崩溃。当它出现的时候，它经常会在磁盘上留下一个被称为“<ruby>核心转储<rt>core dump</rt></ruby>”的数据文件。该文件包含有关系统崩溃时的相关数据，可能有助于确定发生崩溃的原因。通常开发者要求提供 “<ruby>回溯<rt>backtrace</rt></ruby>” 形式的数据，以显示导致崩溃的指令流。开发人员可以使用它来修复 bug 以改进系统。如果系统发生了崩溃，以下是如何轻松生成 <ruby>回溯<rt>backtrace</rt></ruby> 的方法。</p><h3 id="从使用-coredumpctl-开始" tabindex="-1">从使用 coredumpctl 开始 <a class="header-anchor" href="#从使用-coredumpctl-开始" aria-label="Permalink to “从使用 coredumpctl 开始”">​</a></h3>',4)),l("p",null,[t[1]||(t[1]=e("大多数 Fedora 系统使用",-1)),i(s,{href:"https://github.com/abrt/abrt"},{default:a(()=>[...t[0]||(t[0]=[e("自动错误报告工具（ABRT）",-1)])]),_:1}),t[2]||(t[2]=e("来自动捕获崩溃文件并记录 bug。但是，如果你禁用了此服务或删除了该软件包，则此方法可能会有所帮助。",-1))]),t[22]||(t[22]=d('<p>如果你遇到系统崩溃，请首先确保你运行的是最新的软件。更新通常包含修复程序，这些更新通常含有已经发现的会导致严重错误和崩溃的错误的修复。当你更新后，请尝试重现导致错误的情况。</p><p>如果崩溃仍然发生，或者你已经在运行最新的软件，那么可以使用有用的 <code>coredumpctl</code> 工具。此程序可帮助查找和处理崩溃。要查看系统上所有核心转储列表，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl list</span></span></code></pre></div><p>如果你看到比预期长的列表，请不要感到惊讶。有时系统组件在后台默默地崩溃，并自行恢复。快速查找今天的转储的简单方法是使用 <code>-since</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl list --since=today</span></span></code></pre></div><p>“PID” 列包含用于标识转储的进程 ID。请注意这个数字，因为你会之后再用到它。或者，如果你不想记住它，使用下面的命令将它赋值给一个变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MYPID=&lt;PID&gt;</span></span></code></pre></div><p>要查看关于核心转储的信息，请使用此命令（使用 <code>$MYPID</code> 变量或替换 PID 编号）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl info $MYPID</span></span></code></pre></div><h3 id="安装-debuginfo-包" tabindex="-1">安装 debuginfo 包 <a class="header-anchor" href="#安装-debuginfo-包" aria-label="Permalink to “安装 debuginfo 包”">​</a></h3><p>在核心转储中的数据以及原始代码中的指令之间调试符号转义。这个符号数据可能相当大。与大多数用户运行在 Fedora 系统上的软件包不同，符号以 “debuginfo” 软件包的形式安装。要确定你必须安装哪些 debuginfo 包，请先运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl gdb $MYPID</span></span></code></pre></div>',12)),l("p",null,[t[4]||(t[4]=e("这可能会在屏幕上显示大量信息。最后一行可能会告诉你使用 ",-1)),t[5]||(t[5]=l("code",null,"dnf",-1)),t[6]||(t[6]=e(" 安装更多的 debuginfo 软件包。",-1)),i(s,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:a(()=>[...t[3]||(t[3]=[e("用 sudo ",-1)])]),_:1}),t[7]||(t[7]=e("运行该命令以安装：",-1))]),t[23]||(t[23]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf debuginfo-install &lt;packages...&gt;</span></span></code></pre></div><p>然后再次尝试 <code>coredumpctl gdb $MYPID</code> 命令。<strong>你可能需要重复执行此操作</strong>，因为其他符号会在回溯中展开。</p><h3 id="捕获回溯" tabindex="-1">捕获回溯 <a class="header-anchor" href="#捕获回溯" aria-label="Permalink to “捕获回溯”">​</a></h3><p>在调试器中运行以下命令以记录信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set logging file mybacktrace.txt</span></span>
<span class="line"><span>set logging on</span></span></code></pre></div><p>你可能会发现关闭分页有帮助。对于长的回溯，这可以节省时间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set pagination off</span></span></code></pre></div><p>现在运行回溯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>thread apply all bt full</span></span></code></pre></div><p>现在你可以输入 <code>quit</code> 来退出调试器。<code>mybacktrace.txt</code> 包含可附加到 bug 或问题的追踪信息。或者，如果你正在与某人实时合作，则可以将文本上传到 pastebin。无论哪种方式，你现在可以向开发人员提供更多的帮助来解决问题。</p><hr><p>作者简介：</p><p>Paul W. Frields</p><p>Paul W. Frields 自 1997 年以来一直是 Linux 用户和爱好者，并于 2003 年在 Fedora 发布不久后加入 Fedora。他是 Fedora 项目委员会的创始成员之一，从事文档、网站发布、宣传、工具链开发和维护软件。他于 2008 年 2 月至 2010 年 7 月加入 Red Hat，担任 Fedora 项目负责人，现任红帽公司工程部经理。他目前和妻子和两个孩子住在弗吉尼亚州。</p><hr>`,15)),l("p",null,[t[9]||(t[9]=e("via: ",-1)),i(s,{href:"https://fedoramagazine.org/file-better-bugs-coredumpctl/"},{default:a(()=>[...t[8]||(t[8]=[e("https://fedoramagazine.org/file-better-bugs-coredumpctl/",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("作者：",-1)),i(s,{href:"https://fedoramagazine.org/author/pfrields/"},{default:a(()=>[...t[10]||(t[10]=[e("Paul W. Frields",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:a(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
